import logging
from typing import Optional

logger = logging.getLogger(__name__)

def read_threshold(config: dict, key: str = "threshold") -> int:
    """Read a threshold from config with a default of 30."""
    return config.get(key, 30)


def check_exceeds(value: int, threshold: int) -> bool:
    """Return True if value exceeds threshold."""
    return value > threshold


def log_warning_if_exceeded(value: int, threshold: int) -> None:
    """Log a warning if value exceeds threshold."""
    if check_exceeded(value, threshold):
        logger.warning(
            f"Value {value} exceeds threshold {threshold}"
        )


def module_body(config: dict) -> None:
    threshold = read_threshold(config, "threshold")
    log_warning_if_exceeded(config.get("value", 0), threshold)
